Item.method_code:
// URL can be something like this: 
// $[HTTP_PREFIX_SERVER]$[HTTP_HOST_SERVER]$[HTTP_PORT_SERVER]$[HTTP_PATH_SERVER]/Server/innovatorserver.aspx
// In this case need a special request to server to transform it using server settings.
const string defaultVaultId = "67BBB9204FE84A8981ED8313049BA06C";

int count = this.getItemCount();
for (int i = 0; i < count; i ++)
{
	Item item = this.getItemByIndex(i);
	string pattern = item.getProperty("vault_url_pattern", null);
	if (pattern != null)
	{
		// Cloud related operating parameters checks only for Default vault.
		if (item.getID() == defaultVaultId)
		{
			pattern = (string)serverConnection.GetOperatingParameter("VaultUrlPatternDefaultVault", pattern);
			string internalUrl = (string)serverConnection.GetOperatingParameter("VaultUrlPatternInternalDefaultVault", null);

			if (!string.IsNullOrEmpty(internalUrl))
			{
				item.setProperty("vault_url_internal", internalUrl);
			}
		}

		string url = CCO.ServerEnvironment.TransformUrl(pattern);
		item.setProperty("vault_url", url);
	}
}
return this;
